# shellcheck shell=bash
# build-extlibs.sh -- stage `extlibs` (lane xlibs-ext), sourced by build.sh.
# Static .a only, both arches, on top of the clientlibs prefix:
#   libXdamage libXcomposite libXcursor libXrandr libXinerama libXres libXpm
#   libjpeg-turbo (vendored tarball) expat fontconfig libXft
# plus the §4.4 font data tree in $HB_DISK_DIR/X11/ (FONTS.CNF + FONTS/*.TTF)
# and the M2 Xft/Xpm smoke client (build/<arch>/smoke/XFTSMOKE.BIN).
#
# Fontconfig runtime model (icewm.md §4.4): compiled-in default config is
# /X11/FONTS.CNF (FONTCONFIG_PATH=/X11, FONTCONFIG_FILE="FONTS.CNF"), so it
# works with or without the FONTCONFIG_FILE env XSESSION sets.  Fonts live in
# /X11/FONTS with 8.3 names (fontconfig reads the family from the font, not
# the file name, so no FAT LFN dependency).  Cache dir /TMP/FCCACHE; a failed
# cache write is harmless (fontconfig just rescans).


_ex_xdamage()    { hb_autotools libXdamage    libXdamage-1.1.7.tar.xz; }
_ex_xcomposite() { hb_autotools libXcomposite libXcomposite-0.4.7.tar.xz -- --without-xmlto; }
_ex_xcursor()    {
  # Icon/cursor theme search path: an on-disk location that exists on the
  # IceWM image (no cursor themes shipped -> core cursor font fallback).
  hb_autotools libXcursor libXcursor-1.2.3.tar.xz -- \
    --with-icondir=/X11/ICONS --with-cursorpath=/X11/ICONS
}
_ex_xrandr()     { hb_autotools libXrandr    libXrandr-1.5.5.tar.xz    -- --enable-malloc0returnsnull=no; }
_ex_xinerama()   { hb_autotools libXinerama  libXinerama-1.1.6.tar.xz  -- --enable-malloc0returnsnull=no; }
_ex_xres()       { hb_autotools libXres      libXres-1.2.3.tar.xz      -- --enable-malloc0returnsnull=no; }
_ex_xpm() {
  # No popen()-based .Z/.gz readers (HobbyOS has no /bin/sh pipeline).
  hb_autotools libXpm libXpm-3.5.20.tar.xz -- \
    --disable-open-zfile --disable-stat-zfile --disable-unit-tests --without-glib
}

_ex_jpeg() {
  # Plain C codec: no SIMD (no NASM cross path, no runtime CPU probing), no
  # TurboJPEG API, static only.  IceWM uses the libjpeg API.
  hb_cmake libjpeg-turbo libjpeg-turbo-3.1.0.tar.gz -- \
    -DENABLE_SHARED=OFF -DENABLE_STATIC=ON -DWITH_SIMD=OFF -DWITH_TURBOJPEG=OFF \
    -DWITH_JAVA=OFF -DWITH_FUZZ=OFF -DWITH_12BIT=ON -DREQUIRE_SIMD=OFF
}

_ex_expat() {
  # Hash-salt entropy: HobbyOS libc has getentropy() (<sys/random.h>, over
  # SYS_GETRANDOM) but configure's probe only includes <unistd.h>, so force
  # it; no /dev/urandom (and libc lacks O_CLOEXEC, which that path uses).
  hb_autotools expat expat-2.9.0.tar.xz -- \
    --without-docbook --without-xmlwf --without-examples --without-tests \
    --with-getentropy --without-dev-urandom --without-getrandom --without-sys-getrandom \
    --without-arc4random --without-arc4random-buf
}

_ex_fontconfig() {
  local pkg=fontconfig tb=fontconfig-2.18.3.tar.xz
  hb_want $pkg || return 0
  local cfg=(
    --disable-docs --disable-docbook --disable-nls --disable-iconv --disable-cache-build
    --disable-libxml2 --with-expat="$HB_PREFIX"
    --with-baseconfigdir=/X11 --with-configdir=/X11/FCCONF.D --with-templatedir=/X11/FCTMPL
    --with-xmldir=/X11/FCXML --with-default-fonts=/X11/FONTS --with-cache-dir=/TMP/FCCACHE
    --with-arch="$HB_CPU"
    # Cross run-test answers: clang builtin va_copy; repo libc vsnprintf
    # returns the C99 would-be length (src/libc printf core).
    ac_cv_va_copy=C99 fc_cv_c99_vsnprintf=yes
    "CPPFLAGS=$CPPFLAGS -DFONTCONFIG_FILE=\\\"FONTS.CNF\\\""
  )
  local key; key="$(hb_key $pkg $tb "r1 ${cfg[*]}")"
  if hb_done $pkg "$key"; then hb_log "$pkg: cached"; return 0; fi
  (
    hb_pkg_lock $pkg
    hb_done $pkg "$key" && exit 0
    hb_log "$pkg: building"; : > "$HB_LOG_DIR/$pkg.log"
    local src b; src="$(hb_src $pkg $tb)"; b="$HB_OBJ_DIR/$pkg"
    rm -rf "$b"; mkdir -p "$b"; cd "$b"
    # shellcheck disable=SC2086
    hb_run $pkg "$src/configure" $HB_CONFIGURE_ARGS "${cfg[@]}"
    # Library + headers + .pc only: the fc-* tools, conf.d and the cache
    # directory (install-data-hook mkdirs /TMP/FCCACHE on the HOST) are not
    # wanted -- the on-disk config is generated by _ex_fontdata.
    local d
    for d in fontconfig fc-case fc-lang fc-const fc-genericfamily src; do
      hb_run $pkg make -j"$HB_JOBS" -C "$d"
    done
    hb_run $pkg make -C fontconfig install
    hb_run $pkg make -C src install-libLTLIBRARIES
    hb_run $pkg make install-pkgconfigDATA
    find "$HB_PREFIX/lib" -maxdepth 1 -name '*.la' -delete 2>/dev/null || true
    hb_mark $pkg "$key"; hb_log "$pkg: ok"
  )
}

_ex_xft() { hb_autotools libXft libXft-2.3.9.tar.xz -- --enable-malloc0returnsnull=no; }

# §4.4 font data: /X11/FONTS.CNF + /X11/FONTS/<8.3>.TTF from the vendored
# DejaVu 2.37 zip (sha256-verified here; extracted into a fresh dir).
# Sans / Sans Mono / Serif in 4 styles each (+ Sans Condensed regular/bold).
_ex_fontdata() {
  hb_want fontdata || return 0
  local zip="$HB_REPO/third_party/fonts/dejavu-fonts-ttf-2.37.zip"
  ( cd "$HB_REPO/third_party/fonts" && sha256sum -c --quiet dejavu-fonts-ttf-2.37.zip.sha256 ) \
    || hb_die "dejavu zip sha256 mismatch"
  local x="$HB_OBJ_DIR/fontdata"; rm -rf "$x"; mkdir -p "$x"
  unzip -q "$zip" 'dejavu-fonts-ttf-2.37/ttf/*' -d "$x"
  local t="$x/dejavu-fonts-ttf-2.37/ttf" out="$HB_DISK_DIR/X11"
  rm -rf "$out/FONTS"; mkdir -p "$out/FONTS"
  local m src dst
  # <upstream name>:<8.3 on-disk name>
  for m in DejaVuSans.ttf:DJVSANS.TTF DejaVuSans-Bold.ttf:DJVSANSB.TTF \
           DejaVuSans-Oblique.ttf:DJVSANSI.TTF DejaVuSans-BoldOblique.ttf:DJVSANBI.TTF \
           DejaVuSansCondensed.ttf:DJVSCND.TTF DejaVuSansCondensed-Bold.ttf:DJVSCNDB.TTF \
           DejaVuSansMono.ttf:DJVMONO.TTF DejaVuSansMono-Bold.ttf:DJVMONOB.TTF \
           DejaVuSansMono-Oblique.ttf:DJVMONOI.TTF DejaVuSansMono-BoldOblique.ttf:DJVMONBI.TTF \
           DejaVuSerif.ttf:DJVSERIF.TTF DejaVuSerif-Bold.ttf:DJVSERFB.TTF \
           DejaVuSerif-Italic.ttf:DJVSERFI.TTF DejaVuSerif-BoldItalic.ttf:DJVSERBI.TTF; do
    src="${m%%:*}"; dst="${m##*:}"
    install -m 0644 "$t/$src" "$out/FONTS/$dst"
  done
  install -m 0644 "$x/dejavu-fonts-ttf-2.37/LICENSE" "$out/FONTS/LICENSE.TXT" 2>/dev/null \
    || unzip -p "$zip" dejavu-fonts-ttf-2.37/LICENSE > "$out/FONTS/LICENSE.TXT"
  cat > "$out/FONTS.CNF" <<'EOF'
<?xml version="1.0"?>
<!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">
<!-- HobbyOS DESKTOP=icewm fontconfig configuration (generated by
     third_party/x11/build-extlibs.sh).  Only the DejaVu set in /X11/FONTS. -->
<fontconfig>
  <dir>/X11/FONTS</dir>
  <cachedir>/TMP/FCCACHE</cachedir>
  <config><rescan><int>0</int></rescan></config>

  <alias binding="same"><family>sans-serif</family><prefer><family>DejaVu Sans</family></prefer></alias>
  <alias binding="same"><family>sans</family><prefer><family>DejaVu Sans</family></prefer></alias>
  <alias binding="same"><family>serif</family><prefer><family>DejaVu Serif</family></prefer></alias>
  <alias binding="same"><family>monospace</family><prefer><family>DejaVu Sans Mono</family></prefer></alias>
  <alias binding="same"><family>mono</family><prefer><family>DejaVu Sans Mono</family></prefer></alias>
  <alias binding="same"><family>fixed</family><prefer><family>DejaVu Sans Mono</family></prefer></alias>
  <!-- Anything unknown (Helvetica, Arial, ...) falls back to DejaVu Sans. -->
  <match target="pattern">
    <edit name="family" mode="append_last"><string>DejaVu Sans</string></edit>
  </match>

  <match target="font">
    <edit name="antialias" mode="assign"><bool>true</bool></edit>
    <edit name="hinting" mode="assign"><bool>true</bool></edit>
    <edit name="hintstyle" mode="assign"><const>hintslight</const></edit>
    <edit name="rgba" mode="assign"><const>none</const></edit>
  </match>
</fontconfig>
EOF
  hb_log "fontdata: $out/FONTS.CNF + $(find "$out/FONTS" -name '*.TTF' | wc -l) TTFs ($(du -sh "$out/FONTS" | cut -f1))"
}

# M2 gate: an Xft + Xpm client linked as a flat .BIN.  Lands in
# build/<arch>/smoke/ (never bin/), like clientlibs' XSMOKE.BIN.
_ex_smoke() {
  hb_want smoke || return 0
  local o="$HB_OBJ_DIR/smoke"; mkdir -p "$o" "$HB_BUILD/smoke"
  local mods="xft fontconfig freetype2 xpm xrender xext x11 xcursor xrandr xinerama xcomposite xdamage xfixes libjpeg"
  # shellcheck disable=SC2046
  hb_run smoke "$CC" $CFLAGS $("$PKG_CONFIG" --cflags $mods) \
    -c "$HB_X11_DIR/smoke/xftsmoke.c" -o "$o/xftsmoke.o"
  # shellcheck disable=SC2046
  hb_run smoke hb_link_flat "$HB_BUILD/smoke/XFTSMOKE.BIN" "$o/xftsmoke.o" \
    $("$PKG_CONFIG" --libs $mods)
  hb_log "smoke: $HB_BUILD/smoke/XFTSMOKE.BIN ($(stat -c %s "$HB_BUILD/smoke/XFTSMOKE.BIN") bytes)"
}

stage_extlibs() {
  _ex_xdamage
  _ex_xcomposite
  _ex_xcursor
  _ex_xrandr
  _ex_xinerama
  _ex_xres
  _ex_xpm
  _ex_jpeg
  _ex_expat
  _ex_fontconfig
  _ex_xft
  _ex_fontdata
  _ex_smoke
}
